<template>
  <section class="garden">
    <header><div><span>MEMORY GARDEN</span><h3>Keep the moments<br />that changed you.</h3><p>Save a small piece of what you made, learned, noticed, or felt. Over time, your private garden becomes evidence of growth.</p></div><b>{{ entries.length }}<small>BLOOMS</small></b></header>
    <div class="garden-shell"><form @submit.prevent="plant"><label>WHAT DO YOU WANT TO REMEMBER?<textarea v-model.trim="draft" maxlength="380" placeholder="I finally understood… / I made… / I helped…"></textarea></label><div><label>SEASON<select v-model="kind"><option value="made">Made</option><option value="learned">Learned</option><option value="helped">Helped</option><option value="noticed">Noticed</option></select></label><button type="submit">Plant memory ↗</button></div></form><div class="garden-bed"><div v-if="entries.length === 0" class="empty"><i>✿</i><strong>Your garden is waiting.</strong><p>Plant the first moment you do not want to lose.</p></div><button v-for="(entry, index) in entries" :key="entry.id" :class="`bloom bloom-${entry.kind}`" :style="bloomStyle(index)" type="button" :aria-label="entry.text" @click="selectedId = entry.id"><i>{{ glyph(entry.kind) }}</i><span v-if="selectedId === entry.id"><b>{{ entry.kind }}</b>{{ entry.text }}<small>{{ entry.createdAt }}</small></span></button></div></div>
    <footer><p>{{ message || 'Your garden stays private and local to this device.' }}</p><button type="button" :disabled="entries.length === 0" @click="clear">Clear garden</button></footer>
  </section>
</template>

<script setup lang="ts">
import { onMounted, ref } from "vue";

type MemoryKind = "made" | "learned" | "helped" | "noticed";
type Memory = { id: string; text: string; kind: MemoryKind; createdAt: string };
const storageKey = "top-memory-garden-v1";
const draft = ref("");
const kind = ref<MemoryKind>("made");
const entries = ref<Memory[]>([]);
const selectedId = ref<string | null>(null);
const message = ref("");

function plant(): void { if (!draft.value) { message.value = "NAME THE MOMENT FIRST"; return; } const entry: Memory = { id: crypto.randomUUID(), text: draft.value, kind: kind.value, createdAt: new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric", year: "numeric" }).format(new Date()) }; entries.value = [entry, ...entries.value].slice(0, 36); draft.value = ""; selectedId.value = entry.id; persist("MEMORY PLANTED"); }
function persist(nextMessage: string): void { try { localStorage.setItem(storageKey, JSON.stringify(entries.value)); message.value = nextMessage; } catch { message.value = "LOCAL STORAGE IS FULL"; } }
function clear(): void { entries.value = []; selectedId.value = null; persist("GARDEN CLEARED"); }
function bloomStyle(index: number): { left: string; top: string; animationDelay: string } { return { left: `${12 + ((index * 29) % 72)}%`, top: `${16 + ((index * 37) % 64)}%`, animationDelay: `${(index % 5) * .18}s` }; }
function glyph(value: MemoryKind): string { return { made: "✦", learned: "◌", helped: "↗", noticed: "◒" }[value]; }
onMounted(() => { try { const saved = JSON.parse(localStorage.getItem(storageKey) ?? "[]") as unknown; entries.value = Array.isArray(saved) ? saved.filter((entry): entry is Memory => Boolean(entry) && typeof entry === "object" && typeof (entry as Memory).id === "string" && typeof (entry as Memory).text === "string") : []; } catch { entries.value = []; } });
</script>

<style scoped>
.garden { background:linear-gradient(145deg,rgba(27,54,44,.84),rgba(5,14,19,.95)); border:1px solid rgba(217,255,113,.27); border-radius:26px 26px 7px 26px; box-shadow:inset 0 1px rgba(239,255,218,.07),0 25px 75px rgba(0,0,0,.25); grid-column:span 3; overflow:hidden; padding:clamp(25px,4vw,46px); position:relative; }.garden::after { background:radial-gradient(circle,rgba(217,255,113,.14),transparent 68%); bottom:-240px; content:""; height:480px; position:absolute; right:-180px; width:480px; }.garden header { align-items:flex-start; display:flex; justify-content:space-between; position:relative; }.garden header > div > span { color:var(--top-lime); font-family:var(--top-mono); font-size:9px; letter-spacing:.17em; }.garden h3 { font-family:var(--top-display); font-size:clamp(31px,3.8vw,54px); font-weight:750; letter-spacing:-.08em; line-height:.89; margin:13px 0; }.garden header p { color:var(--top-muted); line-height:1.65; max-width:600px; }.garden header > b { align-items:center; border:1px solid rgba(217,255,113,.45); border-radius:50%; color:var(--top-lime); display:flex; flex-direction:column; font-family:var(--top-display); font-size:24px; height:66px; justify-content:center; width:66px; }.garden header b small { font-family:var(--top-mono); font-size:6px; letter-spacing:.13em; margin-top:3px; }.garden-shell { display:grid; gap:13px; grid-template-columns:300px minmax(0,1fr); margin-top:28px; position:relative; }.garden form { background:rgba(3,10,15,.7); border:1px solid rgba(217,255,113,.2); border-radius:16px 16px 4px 16px; padding:17px; }.garden label { color:rgba(215,237,203,.67); display:block; font-family:var(--top-mono); font-size:8px; letter-spacing:.13em; }.garden textarea,.garden select { background:rgba(2,6,11,.68); border:1px solid rgba(217,255,113,.24); border-radius:10px 10px 3px 10px; color:var(--top-ink); display:block; font:inherit; font-size:12px; margin-top:8px; outline:0; padding:11px; width:100%; }.garden textarea { height:160px; resize:vertical; }.garden form > div { align-items:flex-end; display:flex; gap:9px; margin-top:14px; }.garden form > div label { flex:1; }.garden form button { background:linear-gradient(110deg,var(--top-lime),var(--top-cyan)); border:0; border-radius:10px 10px 3px 10px; color:#07100d; cursor:pointer; font-family:var(--top-display); font-size:12px; font-weight:800; padding:12px; }.garden-bed { background:radial-gradient(circle at center,rgba(217,255,113,.13),transparent 28%),rgba(3,9,14,.74); border:1px solid rgba(217,255,113,.19); border-radius:19px 19px 5px 19px; min-height:350px; overflow:hidden; position:relative; }.garden-bed::before { background-image:radial-gradient(rgba(217,255,113,.2) 1px,transparent 1px); background-size:24px 24px; content:""; inset:0; mask-image:radial-gradient(circle at center,black,transparent 78%); opacity:.35; pointer-events:none; position:absolute; }.bloom { align-items:center; animation:bloom-in .6s both cubic-bezier(.2,.9,.25,1); background:color-mix(in srgb,var(--bloom) 18%,transparent); border:1px solid color-mix(in srgb,var(--bloom) 65%,transparent); border-radius:50% 50% 48% 52% / 50% 52% 48% 50%; color:var(--bloom); cursor:pointer; display:flex; height:35px; justify-content:center; padding:0; position:absolute; transform:translate(-50%,-50%); transition:.2s ease; width:35px; z-index:2; }.bloom:hover,.bloom:focus { box-shadow:0 0 28px color-mix(in srgb,var(--bloom) 45%,transparent); scale:1.15; }.bloom i { font-size:14px; font-style:normal; }.bloom span { background:rgba(4,10,16,.96); border:1px solid color-mix(in srgb,var(--bloom) 45%,transparent); border-radius:12px 12px 3px 12px; color:var(--top-ink); font-size:11px; left:20px; line-height:1.45; min-width:185px; padding:12px; position:absolute; text-align:left; top:20px; z-index:3; }.bloom span b,.bloom span small { color:var(--bloom); display:block; font-family:var(--top-mono); font-size:7px; letter-spacing:.12em; margin-bottom:5px; text-transform:uppercase; }.bloom span small { color:var(--top-muted); margin:7px 0 0; }.bloom-made { --bloom:var(--top-pink); }.bloom-learned { --bloom:var(--top-cyan); }.bloom-helped { --bloom:var(--top-lime); }.bloom-noticed { --bloom:var(--top-violet); }.empty { left:50%; max-width:250px; position:absolute; text-align:center; top:50%; transform:translate(-50%,-50%); }.empty i { color:var(--top-lime); display:block; font-size:38px; font-style:normal; }.empty strong { display:block; font-family:var(--top-display); font-size:23px; letter-spacing:-.06em; margin-top:8px; }.empty p { color:var(--top-muted); font-size:11px; line-height:1.55; margin-top:7px; }.garden footer { align-items:center; border-top:1px solid rgba(217,255,113,.13); display:flex; justify-content:space-between; margin-top:17px; padding-top:17px; position:relative; }.garden footer p { color:rgba(213,234,202,.54); font-size:11px; }.garden footer button { background:transparent; border:1px solid rgba(217,255,113,.23); border-radius:999px; color:var(--top-lime); cursor:pointer; font-family:var(--top-mono); font-size:8px; padding:10px 13px; }.garden footer button:disabled { cursor:not-allowed; opacity:.35; } @keyframes bloom-in { from { opacity:0; scale:.2; } to { opacity:1; scale:1; } }
@media (max-width:800px) { .garden { grid-column:span 1; padding:24px; }.garden header,.garden footer { align-items:flex-start; flex-direction:column; gap:13px; }.garden-shell { grid-template-columns:1fr; }.garden-bed { min-height:310px; } }
</style>
